		sha: typeof stamp?.sha === "string" && stamp.sha ? stamp.sha : null,
		builtAt: typeof stamp?.builtAt === "string" && stamp.builtAt ? stamp.builtAt : null,
		dirty: typeof stamp?.dirty === "boolean" ? stamp.dirty : null,
	};
